<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); ?>
<section class="onboarding-hero panel"><div><span class="eyebrow">Démarrage guidé</span><h2>Votre premier calendrier, étape par étape</h2><p>Terminez ces actions pour disposer d’un espace réellement exploitable par votre équipe.</p></div><div class="onboarding-score"><strong><?= (int)$progress ?>%</strong><span><?= (int)$done ?>/<?= count($steps) ?> étapes</span></div></section>
<div class="onboarding-progress" aria-label="Progression"><span style="width:<?= (int)$progress ?>%"></span></div>
<section class="onboarding-list"><?php foreach($steps as$index=>$step):?><article class="panel <?= $step['done']?'is-done':'' ?>"><span class="onboarding-index"><?= $step['done']?'✓':str_pad((string)($index+1),2,'0',STR_PAD_LEFT) ?></span><div><h3><?= $e($step['title']) ?></h3><p><?= $e($step['description']) ?></p></div><a class="button <?= $step['done']?'secondary':'primary' ?>" href="<?= $e($step['href']) ?>"><?= $e($step['done']?'Revoir':$step['action']) ?></a></article><?php endforeach?></section>
